(5719729, 832425, 37252, '<td valign="top">Such lush green grass. Right now all I see is snow where my grass should be. lol</td>', 'Such lush green grass. Right now all I see is snow where my grass should be. lol', '2009-11-09 03:24:51.000000', NULL, 1),
(5719731, 831671, 37252, '<td valign="top">Fantastic, and most likely a ribbon winner. I wonder ....did you just happen to see him after taking your steps, or did you have to stand and wait awhile for him to show up?</td>', 'Fantastic, and most likely a ribbon winner. I wonder ....did you just happen to see him after taking your steps, or did you have to stand and wait awhile for him to show up?', '2009-11-09 03:26:21.000000', NULL, 1),
