(5719765, 831237, 110744, '<td valign="top">That is amazing. All the houses look exactly the same. I love it.</td>', 'That is amazing. All the houses look exactly the same. I love it.', '2009-11-09 03:59:10.000000', NULL, 1),
(5719766, 832284, 37252, '<td valign="top">Good use of that wide angle lens! Sure made for an interesting perspective.</td>', 'Good use of that wide angle lens! Sure made for an interesting perspective.', '2009-11-09 04:00:52.000000', NULL, 1),
(5719768, 832595, 37252, '<td valign="top">Is this truly following the instructions of from YOUR HOME DOOR walking 35 steps, turn and go 6 steps, turn again and take 6 steps? Kinda hard to believe this one, but what the heck, there have been others I doubted too.</td>', 'Is this truly following the instructions of from YOUR HOME DOOR walking 35 steps, turn and go 6 steps, turn again and take 6 steps? Kinda hard to believe this one, but what the heck, there have been others I doubted too.', '2009-11-09 04:03:37.000000', NULL, 1),
(5719770, 832279, 37252, '<td valign="top">Creative shot. Great job at finding something more interesting than a cement sidewalk.</td>', 'Creative shot. Great job at finding something more interesting than a cement sidewalk.', '2009-11-09 04:05:02.000000', NULL, 1),
(5719772, 832148, 37252, '<td valign="top">Seriously, you found this fly sitting on a reflective surface by taking 47 steps from your door - with the specified turns? Or was this little guy glued to a reflective surface and you took him with you on the route, then set him down for the shoot? It''s an excellent macro shot. I just can not question whether this meets the challenge in truth.</td>', 'Seriously, you found this fly sitting on a reflective surface by taking 47 steps from your door - with the specified turns? Or was this little guy glued to a reflective surface and you took him with you on the route, then set him down for the shoot? It''s an excellent macro shot. I just can not question whether this meets the challenge in truth.', '2009-11-09 04:08:11.000000', NULL, 1),
(5719773, 831875, 37252, '<td valign="top">Well thank goodness you found him - had this challenge not been announced you may have never found the little lost yo-yo boy.</td>', 'Well thank goodness you found him - had this challenge not been announced you may have never found the little lost yo-yo boy.', '2009-11-09 04:09:24.000000', NULL, 1),
