(5728113, 832374, 90323, '<td valign="top">Good shot. Better if the bee was in focus and the key piece of the shot</td>', 'Good shot. Better if the bee was in focus and the key piece of the shot', '2009-11-15 20:44:46.000000', NULL, 1),
(5728114, 832572, 90323, '<td valign="top">Wow. Love the desaturated(?) colors... the faded yellows and orange.</td>', 'Wow. Love the desaturated(?) colors... the faded yellows and orange.', '2009-11-15 20:45:14.000000', NULL, 1),
(5728115, 831820, 90323, '<td valign="top">I really love the bee being the focs of the shot. In this picture I wish the colors were more vibrant.</td>', 'I really love the bee being the focs of the shot. In this picture I wish the colors were more vibrant.', '2009-11-15 20:45:44.000000', NULL, 1),
(5728117, 832356, 90323, '<td valign="top">Gorgeous sky! I love this picture. I think all the elements are really well placed, horizon, sign, etc... if this is outside of your backyard I''m jealous.</td>', 'Gorgeous sky! I love this picture. I think all the elements are really well placed, horizon, sign, etc... if this is outside of your backyard I''m jealous.', '2009-11-15 20:46:32.000000', NULL, 1),
(5728118, 832457, 90323, '<td valign="top">One of the coolest photos of a power pole ever...</td>', 'One of the coolest photos of a power pole ever...', '2009-11-15 20:46:57.000000', NULL, 1),
(5728120, 832448, 90323, '<td valign="top">This photo draws the eye to the target perfectly. I love what you''ve done to the colors, you should tell me what you did... :P</td>', 'This photo draws the eye to the target perfectly. I love what you''ve done to the colors, you should tell me what you did... :P', '2009-11-15 20:47:28.000000', NULL, 1),
(5728122, 832596, 90323, '<td valign="top">Perhaps just me, but I found this boring... sorry.</td>', 'Perhaps just me, but I found this boring... sorry.', '2009-11-15 20:47:50.000000', NULL, 1),
(5728124, 832549, 90323, '<td valign="top">Great photo, but not the most interesting subject.</td>', 'Great photo, but not the most interesting subject.', '2009-11-15 20:48:19.000000', NULL, 1),
(5728125, 832406, 90323, '<td valign="top">What a curious looking little fellow! I like your oranges and the grain effect of the iso you chose. You feel the insect as having motion in the shot, like he''s checking you out. Good choice of focus, in my opinion.</td>', 'What a curious looking little fellow! I like your oranges and the grain effect of the iso you chose. You feel the insect as having motion in the shot, like he''s checking you out. Good choice of focus, in my opinion.', '2009-11-15 20:49:20.000000', NULL, 1),
(5728127, 832312, 90323, '<td valign="top">I''m not sure if I love or hate this. It''s a great piece of art, doesn''t look real. I thinks I like it..</td>', 'I''m not sure if I love or hate this. It''s a great piece of art, doesn''t look real. I thinks I like it..', '2009-11-15 20:50:00.000000', NULL, 1),
(5728128, 832311, 90323, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2009-11-15 20:50:20.000000', NULL, 1),
(5728131, 832558, 90323, '<td valign="top">Oh wow. Amazing colors. Wish your depth of field has brought all the front leaves in focus.</td>', 'Oh wow. Amazing colors. Wish your depth of field has brought all the front leaves in focus.', '2009-11-15 20:50:48.000000', NULL, 1),
(5728133, 832488, 90323, '<td valign="top">Not really feeling the colors or subject.</td>', 'Not really feeling the colors or subject.', '2009-11-15 20:51:17.000000', NULL, 1),
(5728134, 832632, 50695, '<td valign="top">Epiphany right before the poop in your eye. I love this. 9</td>', 'Epiphany right before the poop in your eye. I love this. 9', '2009-11-15 20:51:29.000000', NULL, 1),
(5728135, 832626, 90323, '<td valign="top">A little dark for me...</td>', 'A little dark for me...', '2009-11-15 20:51:31.000000', NULL, 1),
(5728136, 832626, 50695, '<td valign="top">magical. otherwordly. 9</td>', 'magical. otherwordly. 9', '2009-11-15 20:51:41.000000', NULL, 1),
(5728137, 832103, 90323, '<td valign="top">That looks like a fiber optic lamp... nice shooting!</td>', 'That looks like a fiber optic lamp... nice shooting!', '2009-11-15 20:52:00.000000', NULL, 1),
(5728138, 831788, 90323, '<td valign="top">Amazing background in this shot!</td>', 'Amazing background in this shot!', '2009-11-15 20:52:25.000000', NULL, 1),
