(5728141, 832557, 90323, '<td valign="top">Wow, that is some crazy coloring.</td>', 'Wow, that is some crazy coloring.', '2009-11-15 20:53:09.000000', NULL, 1),
(5728142, 832600, 50695, '<td valign="top">I just love this, the sharp texture combined with soft gradations in tone. Beautiful. 9</td>', 'I just love this, the sharp texture combined with soft gradations in tone. Beautiful. 9', '2009-11-15 20:53:39.000000', NULL, 1),
(5728143, 832066, 90323, '<td valign="top">Colors are wayyy too saturated</td>', 'Colors are wayyy too saturated', '2009-11-15 20:53:54.000000', NULL, 1),
(5728144, 832457, 50695, '<td valign="top">Stunning high contrast work. Great fulfillment of the challenge. 9</td>', 'Stunning high contrast work. Great fulfillment of the challenge. 9', '2009-11-15 20:53:56.000000', NULL, 1),
(5728145, 832594, 50695, '<td valign="top">Good energy in the composition to match the subject.</td>', 'Good energy in the composition to match the subject.', '2009-11-15 20:54:10.000000', NULL, 1),
