INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5728147, 832380, 90323, '<td valign="top">Nice. Very moody piece.</td>', 'Nice. Very moody piece.', '2009-11-15 20:54:32.000000', NULL, 1),
(5728148, 832621, 50695, '<td valign="top">Not always a fan of selective desaturation, but it creates a strong, disturbing effect here.</td>', 'Not always a fan of selective desaturation, but it creates a strong, disturbing effect here.', '2009-11-15 20:54:45.000000', NULL, 1),
(5728149, 832538, 90323, '<td valign="top">Great action by the folks in the picture</td>', 'Great action by the folks in the picture', '2009-11-15 20:54:53.000000', NULL, 1),
(5728150, 831703, 90323, '<td valign="top">Wow. Jealous of this shot.</td>', 'Wow. Jealous of this shot.', '2009-11-15 20:55:14.000000', NULL, 1),
(5728151, 832337, 90323, '<td valign="top">Best shot of a trailer I''ve seen...</td>', 'Best shot of a trailer I''ve seen...', '2009-11-15 20:55:27.000000', NULL, 1),
(5728152, 832489, 50695, '<td valign="top">Great composition. By only including one eye, you leave representation fighting with abstraction for control of the image. Good, dynamic composition to match the subject. 9</td>', 'Great composition. By only including one eye, you leave representation fighting with abstraction for control of the image. Good, dynamic composition to match the subject. 9', '2009-11-15 20:56:07.000000', NULL, 1),
(5728153, 831541, 90323, '<td valign="top">Feels a bit over exposed..?</td>', 'Feels a bit over exposed..?', '2009-11-15 20:56:19.000000', NULL, 1),
(5728154, 832068, 90323, '<td valign="top">Cute</td>', 'Cute', '2009-11-15 20:56:25.000000', NULL, 1),
(5728156, 832279, 50695, '<td valign="top">very good example of this effect.</td>', 'very good example of this effect.', '2009-11-15 20:56:40.000000', NULL, 1),
(5728157, 832483, 50695, '<td valign="top">Ahhh I like the silence. 9</td>', 'Ahhh I like the silence. 9', '2009-11-15 20:56:54.000000', NULL, 1),
(5728158, 831689, 90323, '<td valign="top">mmm... wish you had taken just once good solid exposure</td>', 'mmm... wish you had taken just once good solid exposure', '2009-11-15 20:56:57.000000', NULL, 1),
(5728159, 831875, 50695, '<td valign="top">I like how this pushes right to the frame. Good energy.</td>', 'I like how this pushes right to the frame. Good energy.', '2009-11-15 20:57:15.000000', NULL, 1),
(5728160, 832619, 90323, '<td valign="top">Wow. Dig the colors, wish the depth of field kept more of the flower in view</td>', 'Wow. Dig the colors, wish the depth of field kept more of the flower in view', '2009-11-15 20:57:17.000000', NULL, 1),
(5728161, 832596, 50695, '<td valign="top">Nice soft balanced image.</td>', 'Nice soft balanced image.', '2009-11-15 20:57:33.000000', NULL, 1),
(5728162, 831643, 90323, '<td valign="top">I like it a lot. Vignette is sort of much...</td>', 'I like it a lot. Vignette is sort of much...', '2009-11-15 20:58:02.000000', NULL, 1),
(5728163, 832604, 90323, '<td valign="top">DoF is perfect. I like everything.</td>', 'DoF is perfect. I like everything.', '2009-11-15 20:58:16.000000', NULL, 1),
(5728165, 832435, 50695, '<td valign="top">Bright exciting image. "X" is not the most dynamic composition, but strong diagonals do lend energy, and the colors are great.</td>', 'Bright exciting image. "X" is not the most dynamic composition, but strong diagonals do lend energy, and the colors are great.', '2009-11-15 20:58:19.000000', NULL, 1),
(5728166, 832371, 50695, '<td valign="top">I like how this draws me in.</td>', 'I like how this draws me in.', '2009-11-15 20:58:31.000000', NULL, 1),
(5728167, 832622, 90323, '<td valign="top">Would like it to be a bit sharper. good shot.</td>', 'Would like it to be a bit sharper. good shot.', '2009-11-15 20:58:41.000000', NULL, 1),
(5728168, 832311, 50695, '<td valign="top">Very good example of the small made large, and fitting for this challenge. 9</td>', 'Very good example of the small made large, and fitting for this challenge. 9', '2009-11-15 20:58:55.000000', NULL, 1),
(5728169, 832355, 90323, '<td valign="top">I think your camera could use a few degrees of rotation counter-clockwise</td>', 'I think your camera could use a few degrees of rotation counter-clockwise', '2009-11-15 20:59:19.000000', NULL, 1),
(5728170, 832562, 50695, '<td valign="top">Good work, good title. 9</td>', 'Good work, good title. 9', '2009-11-15 20:59:30.000000', NULL, 1),
(5728172, 832451, 90323, '<td valign="top">Great photo and title.</td>', 'Great photo and title.', '2009-11-15 20:59:43.000000', NULL, 1),
(5728173, 832382, 50695, '<td valign="top">Lovely composition. Great lines with two well-balanced elements. 9</td>', 'Lovely composition. Great lines with two well-balanced elements. 9', '2009-11-15 21:00:02.000000', NULL, 1),
