(5728180, 831638, 90323, '<td valign="top">Excellent shot</td>', 'Excellent shot', '2009-11-15 21:01:13.000000', NULL, 1),
(5728181, 832449, 90323, '<td valign="top">Great choice of shutter speed, great timing.</td>', 'Great choice of shutter speed, great timing.', '2009-11-15 21:01:26.000000', NULL, 1),
