(5728185, 831653, 90323, '<td valign="top">Oh that''s cool! Great light.</td>', 'Oh that''s cool! Great light.', '2009-11-15 21:02:10.000000', NULL, 1),
(5728186, 832465, 50695, '<td valign="top">Yes, this is a brilliant photo on its own, but also a brilliant execution of the challenge, a transparent example of the ordinary made sublime. Posthumous Blue for you.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/><br/><br/><i>Message edited by author 2009-11-16 13:47:08.</i></td>', 'Yes, this is a brilliant photo on its own, but also a brilliant execution of the challenge, a transparent example of the ordinary made sublime. Posthumous Blue for you. ', '2009-11-15 21:02:13.000000', '2009-11-16 13:47:08.000000', 1),
(5728187, 831146, 50695, '<td valign="top">I don''t know why I love you, but I do.<br/> <br/>I don''t know why I love morning light, either. I have a posthumous yellow ribbon for this subtle quotidian angel whisper.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/yellowpost.jpg'', strrpos(''//blackyak.com/dpc/yellowpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/yellowpost.jpg"/></td>', 'I don''t know why I love you, but I do. I don''t know why I love morning light, either. I have a posthumous yellow ribbon for this subtle quotidian angel whisper. ', '2009-11-15 21:02:15.000000', NULL, 1),
(5728188, 832374, 50695, '<td valign="top">This is a staggering work of hearbreaking genius. It is a perverse piece of weirdness masquerading as a DPC photo. If my parents gave me this speech when I was a boy, I would have run away from home. Posthumous Red Ribbon for you.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/redpost.jpg'', strrpos(''//blackyak.com/dpc/redpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/redpost.jpg"/></td>', 'This is a staggering work of hearbreaking genius. It is a perverse piece of weirdness masquerading as a DPC photo. If my parents gave me this speech when I was a boy, I would have run away from home. Posthumous Red Ribbon for you. ', '2009-11-15 21:02:28.000000', NULL, 1),
