(5728190, 832597, 90323, '<td valign="top">colors are cool if oversaturated a little</td>', 'colors are cool if oversaturated a little', '2009-11-15 21:02:53.000000', NULL, 1),
(5728191, 832365, 90323, '<td valign="top">Hard to make snow interesting. Nice attempt.</td>', 'Hard to make snow interesting. Nice attempt.', '2009-11-15 21:03:06.000000', NULL, 1),
