INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5729048, 832383, 16106, '<td valign="top">Funny that it got an "Honorable" Mention. Kinda ironic. Good example of why these sorts of challenges should be gotten rid of, some people will handicap themselves by limiting themselves to the challenge wording.</td>', 'Funny that it got an "Honorable" Mention. Kinda ironic. Good example of why these sorts of challenges should be gotten rid of, some people will handicap themselves by limiting themselves to the challenge wording.', '2009-11-16 12:57:29.000000', NULL, 0),
(5729060, 832563, 101668, '<td valign="top">Congrats. Lovely picture.</td>', 'Congrats. Lovely picture.', '2009-11-16 13:06:48.000000', NULL, 0),
(5729082, 832383, 90495, '<td valign="top">I take everything back nuzzer. Sorry for calling you a liar.<br/> <br/>Did you take other shots apart from this one? If so, do as many say, enter it in a FS. What if you win it? LOL<br/><br/><i>Message edited by author 2009-11-18 15:31:06.</i></td>', 'I take everything back nuzzer. Sorry for calling you a liar. Did you take other shots apart from this one? If so, do as many say, enter it in a FS. What if you win it? LOL', '2009-11-16 13:25:51.000000', '2009-11-18 15:31:06.000000', 0),
(5729083, 832383, 75618, '<td valign="top">I gave this a LOW vote because I knew it wasn''t 47 steps and I was right. :P</td>', 'I gave this a LOW vote because I knew it wasn''t 47 steps and I was right. :P', '2009-11-16 13:26:31.000000', NULL, 0),
(5729085, 832383, 77521, '<td valign="top">i don''t care if you lived there or not! im sure many more people didn''t meet the challenge criteria, they just didnt say anything about it! still deserved 5th place!! great shot! :]</td>', 'i don''t care if you lived there or not! im sure many more people didn''t meet the challenge criteria, they just didnt say anything about it! still deserved 5th place!! great shot! :]', '2009-11-16 13:27:59.000000', NULL, 0),
(5729087, 832069, 90495, '<td valign="top">Beautiful image Roz. I have never witnessed this before, and I like watching bugs. I''ve seen spiders catch their prey in webs but like this, never. I hope to one day. Ferocious, aren''t they. Oz, bad place to be a fly. lol</td>', 'Beautiful image Roz. I have never witnessed this before, and I like watching bugs. I''ve seen spiders catch their prey in webs but like this, never. I hope to one day. Ferocious, aren''t they. Oz, bad place to be a fly. lol', '2009-11-16 13:29:22.000000', NULL, 0),
(5729088, 832553, 90495, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2009-11-16 13:30:20.000000', NULL, 0),
(5729101, 832383, 111403, '<td valign="top">What fun is a challenge if you cheat to get a score? I''m pretty sure I''m happier with my personal best score than you are with your placement. why, because I followed the rules and made it obvious. Hope you enjoy not having any dignity!</td>', 'What fun is a challenge if you cheat to get a score? I''m pretty sure I''m happier with my personal best score than you are with your placement. why, because I followed the rules and made it obvious. Hope you enjoy not having any dignity!', '2009-11-16 13:38:43.000000', NULL, 0),
(5729111, 831703, 111403, '<td valign="top">Very well deserved Ribbon, congrats!</td>', 'Very well deserved Ribbon, congrats!', '2009-11-16 13:47:08.000000', NULL, 0),
(5729113, 832595, 111403, '<td valign="top">I appreciate your honesty and think even though you couldn''t follow it exactly, you did the next best thing. The shot looks great, congrats!</td>', 'I appreciate your honesty and think even though you couldn''t follow it exactly, you did the next best thing. The shot looks great, congrats!', '2009-11-16 13:48:55.000000', NULL, 0),
(5729116, 831653, 30982, '<td valign="top">VERY creative and I think the photograph works very well!  I like the shallow depth of field and really like the low light shadows from the railing falling across your "steps".  Also, please note the average from your commenters - that''s an excellent indication that your work resonated with those folks, and in many instances, that''s worth more than the total score.</td>', 'VERY creative and I think the photograph works very well!  I like the shallow depth of field and really like the low light shadows from the railing falling across your "steps".  Also, please note the average from your commenters - that''s an excellent indication that your work resonated with those folks, and in many instances, that''s worth more than the total score.', '2009-11-16 13:50:23.000000', NULL, 0),
(5729144, 832563, 90495, '<td valign="top">Loved this shot when voting. Looks like it was shot in studio but I know it wasn''t. Just beautiful.</td>', 'Loved this shot when voting. Looks like it was shot in studio but I know it wasn''t. Just beautiful.', '2009-11-16 13:55:49.000000', NULL, 0),
(5729145, 832594, 111403, '<td valign="top">Should have placed higher! I loved it.</td>', 'Should have placed higher! I loved it.', '2009-11-16 13:56:00.000000', NULL, 0),
(5729164, 832465, 61961, '<td valign="top">I might have overlooked this image if <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=36981" rel="nofollow" target="_blank">Bebe</a> and <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">posthumous</a> hadn''t singled it out.  Intriguing, dreamlike shot.</td>', 'I might have overlooked this image if  Bebe and  posthumous hadn''t singled it out.  Intriguing, dreamlike shot.', '2009-11-16 14:04:15.000000', NULL, 0),
(5729180, 831653, 67258, '<td valign="top">A good entry for the challenge, and a photo that also stands on its own.  I like photos that allow the viewer to develop their own story, and this does just that - good work.</td>', 'A good entry for the challenge, and a photo that also stands on its own.  I like photos that allow the viewer to develop their own story, and this does just that - good work.', '2009-11-16 14:11:49.000000', NULL, 0),
